package com.renthouse.operation;import com.renthouse.auth.*;import com.renthouse.common.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/landlord/dashboard")public class DashboardController{private final JdbcTemplate j;public DashboardController(JdbcTemplate j){this.j=j;}@GetMapping public ApiResponse<Data>get(){CurrentUser.requireRole(UserRole.LANDLORD);long id=CurrentUser.require().id();return ApiResponse.ok(new Data(count("property_unit","occupancy_status='VACANT'",id),count("property_unit","occupancy_status='OCCUPIED'",id),count("appointment","status='PENDING'",id),count("bill","status='PENDING_VERIFICATION'",id),count("repair_ticket","status IN ('PENDING','PROCESSING')",id),sum()));}private long count(String t,String w,long id){String col=t.equals("property_unit")?"landlord_id":"landlord_id";Long v=j.queryForObject("SELECT COUNT(*) FROM "+t+" WHERE "+col+"=? AND "+w,Long.class,id);return v==null?0:v;}private long sum(){Long v=j.queryForObject("SELECT COALESCE(SUM(amount_cent),0) FROM bill WHERE landlord_id=? AND status='PAID'",Long.class,CurrentUser.require().id());return v==null?0:v;}public record Data(long vacantUnits,long occupiedUnits,long pendingAppointments,long pendingVerificationBills,long openRepairs,long paidIncomeCent){}}
